param([switch]$Push = $true)
$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest
$Root = "C:\Users\arauj\grafica-flash"
Set-Location -LiteralPath $Root

function Step([string]$Message) { Write-Host ""; Write-Host "==> $Message" -ForegroundColor Cyan }
function Resolve-Cmd([string]$Name) { foreach ($candidate in @("$Name.cmd", $Name)) { $cmd = Get-Command $candidate -ErrorAction SilentlyContinue; if ($cmd) { return $cmd.Source } }; throw "Command not found: $Name" }
function Run([string]$Command, [string[]]$Arguments) { & $Command @Arguments; if ($LASTEXITCODE -ne 0) { throw "Failed: $Command $($Arguments -join ' ')" } }
function Write-Base64File([string]$Relative, [string]$Base64) {
  $Target = Join-Path $Root $Relative
  $Dir = Split-Path -Parent $Target
  New-Item -ItemType Directory -Path $Dir -Force | Out-Null
  [System.IO.File]::WriteAllBytes($Target, [Convert]::FromBase64String($Base64))
}

$Git = Resolve-Cmd "git"
$Npm = Resolve-Cmd "npm"
$Npx = Resolve-Cmd "npx"

Step "Writing mirrored read-only demo"
Write-Base64File "app/parceiros/demo/layout.tsx" "aW1wb3J0IHR5cGUgeyBSZWFjdE5vZGUgfSBmcm9tICJyZWFjdCI7CmltcG9ydCAiLi4vLi4vcGFpbmVsL3ByZW1pdW0uY3NzIjsKCmV4cG9ydCBkZWZhdWx0IGZ1bmN0aW9uIFBhcmNlaXJvc0RlbW9MYXlvdXQoewogIGNoaWxkcmVuLAp9OiB7CiAgY2hpbGRyZW46IFJlYWN0Tm9kZTsKfSkgewogIHJldHVybiBjaGlsZHJlbjsKfQo="
Write-Host "[OK] app/parceiros/demo/layout.tsx" -ForegroundColor Green
Write-Base64File "components/parceiros/PartnerSystemDemo.tsx" ""
Write-Host "[OK] components/parceiros/PartnerSystemDemo.tsx" -ForegroundColor Green

$Targets = @("app/parceiros/demo/layout.tsx","components/parceiros/PartnerSystemDemo.tsx","app/parceiros/demo/page.tsx")

Step "ESLint"
Run $Npx @("eslint","app/parceiros/demo/page.tsx","app/parceiros/demo/layout.tsx","components/parceiros/PartnerSystemDemo.tsx")

Step "Build"
Run $Npm @("run","build")

Step "Diff check"
Run $Git @("diff","--check","--","app/parceiros/demo/page.tsx","app/parceiros/demo/layout.tsx","components/parceiros/PartnerSystemDemo.tsx")
& $Git --no-pager diff --stat -- "app/parceiros/demo/page.tsx" "app/parceiros/demo/layout.tsx" "components/parceiros/PartnerSystemDemo.tsx"

Step "Commit"
Run $Git @("add","--","app/parceiros/demo/page.tsx","app/parceiros/demo/layout.tsx","components/parceiros/PartnerSystemDemo.tsx")
Run $Git @("diff","--cached","--check","--","app/parceiros/demo/page.tsx","app/parceiros/demo/layout.tsx","components/parceiros/PartnerSystemDemo.tsx")
& $Git diff --cached --quiet -- "app/parceiros/demo/page.tsx" "app/parceiros/demo/layout.tsx" "components/parceiros/PartnerSystemDemo.tsx"
if ($LASTEXITCODE -eq 0) { throw "No demo changes to commit." }
Run $Git @("commit","-m","Espelha painel real no demonstrativo de parceiros","--","app/parceiros/demo/page.tsx","app/parceiros/demo/layout.tsx","components/parceiros/PartnerSystemDemo.tsx")

if ($Push) {
  $branch = (& $Git branch --show-current).Trim()
  Step "Push"
  Run $Git @("push","-u","origin",$branch)
}

Write-Host ""
Write-Host "ORCALY_PARTNER_MIRROR_DEMO_OK=1" -ForegroundColor Green
Write-Host "Shared panel modules: OK" -ForegroundColor Cyan
Write-Host "Premium panel CSS: OK" -ForegroundColor Cyan
Write-Host "Read-only navigation: OK" -ForegroundColor Cyan
Write-Host "No Supabase/API writes: OK" -ForegroundColor Cyan